/**
 * 버튼 [$p.data.get("JSON")]
 */
scwin.btn_exec1_2_onclick = function (e) {
    console.log('$p.data.get("JSON")');
    console.log($p.data.get("JSON"));
	window.check_val = Object.keys($p.data.get("JSON")).length;
};

	scwin.checkVal = function() {
		return window.check_val == 2;
	}	

	scwin.unitTest = function(){
		//init
		WebSquare.wUnit.start();

		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('btn_exec1_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");			

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
